"""Retain closed synthetic browser observations once; never rerun."""
import datetime, hashlib, json, shutil
from pathlib import Path
root=Path(__file__).resolve().parents[2]
dest=Path(__file__).parent/'issue214-responsive-browser-closed'
assert not dest.exists()
dest.mkdir()
cli="### Result\n[\n  {\n    \"method\": \"GET\",\n    \"url\": \"/api/qc/control-charts/series\",\n    \"input\": {\n      \"params\": {\n        \"labId\": \"UI-LAB\"\n      }\n    }\n  },\n  {\n    \"method\": \"GET\",\n    \"url\": \"/api/qc/control-reviews\",\n    \"input\": {\n      \"params\": {\n        \"labId\": \"UI-LAB\"\n      }\n    }\n  },\n  {\n    \"method\": \"GET\",\n    \"url\": \"/api/qc/control-charts\",\n    \"input\": {\n      \"params\": {\n        \"labId\": \"UI-LAB\",\n        \"analysisCode\": \"UI-ANALYTE\",\n        \"methodologyId\": \"UI-METHOD\",\n        \"referenceMaterialId\": \"UI-LOT\",\n        \"referenceName\": \"Synthetic control\",\n        \"lotNumber\": \"LOT-UI-1\"\n      }\n    }\n  },\n  {\n    \"method\": \"GET\",\n    \"url\": \"/api/qc/run-options\",\n    \"input\": {\n      \"params\": {\n        \"analysisCode\": \"UI-ANALYTE\",\n        \"labId\": \"UI-LAB\",\n        \"workItemIds\": \"[\\\"UI-WORK\\\"]\"\n      }\n    }\n  },\n  {\n    \"method\": \"GET\",\n    \"url\": \"/api/qc/run-options\",\n    \"input\": {\n      \"params\": {\n        \"analysisCode\": \"UI-ANALYTE\",\n        \"labId\": \"UI-LAB\",\n        \"workItemIds\": \"[\\\"UI-WORK\\\"]\",\n        \"methodologyId\": \"UI-METHOD\"\n      }\n    }\n  },\n  {\n    \"method\": \"POST\",\n    \"url\": \"/api/qc/runs/start\",\n    \"input\": {\n      \"analysisCode\": \"UI-ANALYTE\",\n      \"labId\": \"UI-LAB\",\n      \"methodologyId\": \"UI-METHOD\",\n      \"instrumentId\": null,\n      \"workItemIds\": [\n        \"UI-WORK\"\n      ],\n      \"referenceMaterialLotId\": \"UI-LOT\"\n    }\n  },\n  {\n    \"method\": \"POST\",\n    \"url\": \"/api/qc/control-limit-proposals/UI-PROPOSAL/approve\",\n    \"input\": {}\n  },\n  {\n    \"method\": \"GET\",\n    \"url\": \"/api/qc/control-charts\",\n    \"input\": {\n      \"params\": {\n        \"labId\": \"UI-LAB\",\n        \"analysisCode\": \"UI-ANALYTE\",\n        \"methodologyId\": \"UI-METHOD\",\n        \"referenceMaterialId\": \"UI-LOT\",\n        \"referenceName\": \"Synthetic control\",\n        \"lotNumber\": \"LOT-UI-1\"\n      }\n    }\n  },\n  {\n    \"method\": \"GET\",\n    \"url\": \"/api/qc/control-charts/series\",\n    \"input\": {\n      \"params\": {\n        \"labId\": \"UI-LAB\"\n      }\n    }\n  },\n  {\n    \"method\": \"GET\",\n    \"url\": \"/api/qc/control-reviews\",\n    \"input\": {\n      \"params\": {\n        \"labId\": \"UI-LAB\"\n      }\n    }\n  },\n  {\n    \"method\": \"GET\",\n    \"url\": \"/api/qc/control-charts\",\n    \"input\": {\n      \"params\": {\n        \"labId\": \"UI-LAB\",\n        \"analysisCode\": \"UI-ANALYTE\",\n        \"methodologyId\": \"UI-METHOD\",\n        \"referenceMaterialId\": \"UI-LOT\",\n        \"referenceName\": \"Synthetic control\",\n        \"lotNumber\": \"LOT-UI-1\"\n      }\n    }\n  },\n  {\n    \"method\": \"POST\",\n    \"url\": \"/api/qc/control-reviews/UI-REVIEW/resolve\",\n    \"input\": {\n      \"outcome\": \"INVESTIGATE_NEW_LIMITS\",\n      \"note\": \"Investigate this frozen series; propose limits through the separate reviewed workflow.\"\n    }\n  },\n  {\n    \"method\": \"GET\",\n    \"url\": \"/api/qc/control-charts\",\n    \"input\": {\n      \"params\": {\n        \"labId\": \"UI-LAB\",\n        \"analysisCode\": \"UI-ANALYTE\",\n        \"methodologyId\": \"UI-METHOD\",\n        \"referenceMaterialId\": \"UI-LOT\",\n        \"referenceName\": \"Synthetic control\",\n        \"lotNumber\": \"LOT-UI-1\"\n      }\n    }\n  },\n  {\n    \"method\": \"GET\",\n    \"url\": \"/api/qc/control-charts/series\",\n    \"input\": {\n      \"params\": {\n        \"labId\": \"UI-LAB\"\n      }\n    }\n  },\n  {\n    \"method\": \"GET\",\n    \"url\": \"/api/qc/control-reviews\",\n    \"input\": {\n      \"params\": {\n        \"labId\": \"UI-LAB\"\n      }\n    }\n  },\n  {\n    \"method\": \"GET\",\n    \"url\": \"/api/qc/control-charts\",\n    \"input\": {\n      \"params\": {\n        \"labId\": \"UI-LAB\",\n        \"analysisCode\": \"UI-ANALYTE\",\n        \"methodologyId\": \"UI-METHOD\",\n        \"referenceMaterialId\": \"UI-LOT\",\n        \"referenceName\": \"Synthetic control\",\n        \"lotNumber\": \"LOT-UI-1\"\n      }\n    }\n  }\n]\n### Ran Playwright code\n```js\nawait page.evaluate('() => window.__uiRequests');\n```\n"
(dest/'requests-cli-original.txt').write_bytes(cli.encode('utf-8'))
requests=json.loads(cli.split('### Result\n',1)[1].split('\n### Ran',1)[0])
posts=[r for r in requests if r['method']=='POST']
assert [r['url'] for r in posts]==['/api/qc/runs/start','/api/qc/control-limit-proposals/UI-PROPOSAL/approve','/api/qc/control-reviews/UI-REVIEW/resolve']
assert posts[0]['input']['referenceMaterialLotId']=='UI-LOT' and posts[2]['input']['outcome']=='INVESTIGATE_NEW_LIMITS'
assert posts[2]['input']['note'].strip()
(dest/'requests-parsed.json').write_bytes((json.dumps(requests,indent=2)+'\n').encode())
for label in ['issue-214','issue-214-responsive']:
 for p in (root/'output/playwright'/label).iterdir():
  if p.is_file():
   target=dest/label/p.name;target.parent.mkdir(exist_ok=True);shutil.copyfile(p,target)
snap=dest/'cli-snapshots';snap.mkdir()
for p in (root/'.playwright-cli').glob('*.yml'):
 if p.name>='page-2026-10-13T19-03' and b'Issue214 detached UI' in p.read_bytes():shutil.copyfile(p,snap/p.name)
observations={'closedUtc':datetime.datetime.now(datetime.UTC).isoformat(),'scope':'actual Chromium rendering of production components with injected synthetic UI API, no database or production connection','status':'PASS_AFTER_RESPONSIVE_CORRECTION','viewports':{'mobile':[390,844],'desktop':[1440,1050]},'firstMobileOverflow':{'viewport':390,'documentWidth':464,'status':'FAILED_RENDERING_FIXED_IN_SUCCESSOR'},'correctedMobile':{'viewport':390,'documentWidth':375},'checks':['recorded limit-basis chart and history rendered','trial outlier remains selected until explicit deselection','explicit exclusion reason and proposal reason required','same proposer cannot approve own proposal','separate named manager approval POST','unbound chart-run sample selection and start disabled','bound lot carried by keyboard-submitted start POST','blank review note refused before POST','Tab/Enter review submits outcome and mandatory note without verdict mutation'],'console':'React development-tools INFO and localhost favicon404 only; no component exception','productionOperations':0}
(dest/'observations.json').write_bytes((json.dumps(observations,indent=2)+'\n').encode())
index={str(p.relative_to(dest)).replace('\\','/'):{'bytes':p.stat().st_size,'sha256':hashlib.sha256(p.read_bytes()).hexdigest()} for p in sorted(dest.rglob('*')) if p.is_file()}
(dest/'index.json').write_bytes((json.dumps(index,indent=2)+'\n').encode())
print(json.dumps({'status':'RETAINED','files':len(index),'productionOperations':0}))

